<template><div class="page"><div class="page-head"><div><h1 class="page-title">用户管理</h1><div class="page-sub">维护系统账号、角色和启用状态</div></div><el-button type="primary" @click="open()"><el-icon><Plus/></el-icon>新增用户</el-button></div><div class="toolbar"><el-input v-model="keyword" placeholder="用户名或真实姓名" style="width:300px" clearable/><el-button type="primary" plain @click="load">查询</el-button></div><el-card class="table-card"><el-table :data="rows"><el-table-column label="用户"><template #default="{row}"><div class="u"><el-avatar>{{row.realName?.slice(0,1)}}</el-avatar><div><b>{{row.realName}}</b><small>@{{row.username}}</small></div></div></template></el-table-column><el-table-column prop="phone" label="手机号"/><el-table-column prop="email" label="邮箱"/><el-table-column label="角色"><template #default="{row}"><el-tag :type="row.roleCode==='ADMIN'?'danger':row.roleCode==='LIBRARIAN'?'warning':'success'">{{role(row.roleCode)}}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-switch v-model="row.status" :active-value="1" :inactive-value="0" @change="quick(row)"/></template></el-table-column><el-table-column label="创建时间" prop="createdAt"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination background layout="total,prev,pager,next" :total="total"/></div></el-card><el-dialog v-model="visible" title="用户信息" width="560"><el-form label-position="top"><div class="grid"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="真实姓名"><el-input v-model="form.realName"/></el-form-item><el-form-item v-if="!form.id" label="初始密码"><el-input v-model="form.password"/></el-form-item><el-form-item label="角色"><el-select v-model="form.roleCode"><el-option label="系统管理员" value="ADMIN"/><el-option label="图书管理员" value="LIBRARIAN"/><el-option label="读者" value="READER"/></el-select></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item></div></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template><script setup lang="ts">import{ref,reactive,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),total=ref(0),keyword=ref(''),visible=ref(false),form=reactive<any>({});onMounted(load);async function load(){const r:any=await api.get('/api/users',{params:{keyword:keyword.value}});rows.value=r.records;total.value=r.total}const role=(v:string)=>({ADMIN:'系统管理员',LIBRARIAN:'图书管理员',READER:'读者'}as any)[v];function open(r:any={}){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r,{password:r.password||'Reader@123',roleCode:r.roleCode||'READER'});visible.value=true}async function save(){form.id?await api.put(`/api/users/${form.id}`,form):await api.post('/api/users',form);ElMessage.success('保存成功');visible.value=false;load()}async function quick(r:any){await api.put(`/api/users/${r.id}`,r)}</script><style scoped>.u{display:flex;gap:10px;align-items:center}.u small{display:block;color:#9aa5b2;margin-top:3px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}</style>

